const ALIAS = {"43": "42", "41": "96"};
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
export async function onRequestGet({ request, env }) {
  const u0 = new URL(request.url), c0 = u0.searchParams.get("c") || "";
  if (ALIAS[c0] && (u0.pathname === "/" || u0.pathname === "/index.html")) {  // e.g. TV 43 merged into hub 42
    const to = new URL(u0); to.searchParams.set("c", ALIAS[c0]); return Response.redirect(to.toString(), 302);
  }
  const m0 = OG[c0];
  // home page: research-report style list (_hub/r/home.html) unless a researched code is asked for
  // (user 19 Oct: categories without real-user research are cut — their old codes land on home too)
  if (!(m0 && m0.r) && (u0.pathname === "/" || u0.pathname === "/index.html")) { try { const hp = await env.ASSETS.fetch(new URL("/r/home", u0.origin)); if (hp.ok) return hp; } catch (e) {} }
  let res = await env.ASSETS.fetch(request);
  if (m0 && m0.r) { try { const rp = await env.ASSETS.fetch(new URL(`/r/${u0.searchParams.get("c")}`, u0.origin)); if (rp.ok) res = rp; } catch (e) {} }
  try {
    const u = u0, m = m0;
    if (!m || !(res.headers.get("content-type") || "").includes("text/html")) return res;
    const own = m.r && m.o;  // report page already carries og:type + og:image of its headline card (gen_reports.py)
    const img = m.o ? `${u.origin}/og/${m.o === 1 ? u.searchParams.get("c") : m.o}.png` : m.s ? `${u.origin}/covers/${m.s}.jpg` : "";
    const tags = (own ? "" : `<meta property="og:type" content="website"><meta property="og:site_name" content="สรุปให้ตัวไหนดี">`) +
      `<meta property="og:title" content="${esc(m.t)}"><meta property="og:description" content="${esc(m.d)}">` +
      `<meta property="og:url" content="${esc(u.href)}">` +
      (img && !own ? `<meta property="og:image" content="${img}">` + (m.o ? `<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">` : "") : "");
    return new HTMLRewriter()
      .on("title", { element(e) { e.setInnerContent(m.t); } })
      .on('meta[name="description"]', { element(e) { e.setAttribute("content", m.d); } })
      .on("head", { element(e) { e.append(tags, { html: true }); } })
      .transform(res);
  } catch (e) { return res; }
}
